mapper.delete:
DELETE FROM tb_purchase_receipt_dt
WHERE purchase_receipt_detail_id = #{purchaseReceiptDetailId, jdbcType=BIGINT}
  AND purchase_receipt_id = #{purchaseReceiptId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}

mapper.sql:
(SELECT rd.quality_inspection_detail_id AS quality_inspection_detail_id, sum(rd.receipt_qty) AS received_qty FROM tb_purchase_receipt_dt rd JOIN tb_purchase_receipt_hd rh ON rh.purchase_receipt_id = rd.purchase_receipt_id AND rh.tenant_id = rd.tenant_id WHERE rh.tenant_id = #{tenantId, jdbcType=BIGINT} AND rh.use_at = 'Y' AND rd.quality_inspection_detail_id IS NOT NULL
AND rh.purchase_receipt_id <> #{excludeReceiptId, jdbcType=BIGINT}
GROUP BY rd.quality_inspection_detail_id)
